
--============================================
--CUSTOMER SHOPPING BEHAVIOR ANALYSIS
--SQL Business Analysis Project
--============================================


--View the first 20 records
SELECT *
FROM customer_behaviour
LIMIT 20;


--============================================
--Q1: What is the total revenue generated by
--male and female customers?
-- ============================================

SELECT
    gender,
    COUNT(*) AS total_customers,
    ROUND(SUM(purchase_amount)::numeric, 2) AS total_revenue,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_purchase_amount
FROM customer_behaviour
GROUP BY gender
ORDER BY total_revenue DESC;


-- ============================================
-- Q2: Which customers used a discount but
-- spent more than the average purchase amount?
-- ============================================

SELECT
    customer_id,
    gender,
    item_purchased,
    purchase_amount,
    discount_applied
FROM customer_behaviour
WHERE discount_applied = 'Yes'
  AND purchase_amount > (
      SELECT AVG(purchase_amount)
      FROM customer_behaviour
  )
ORDER BY purchase_amount DESC;


-- ============================================
-- Q3: Which are the top 5 highest-rated products?
-- ============================================

SELECT
    item_purchased,
    COUNT(*) AS total_reviews,
    ROUND(AVG(review_rating)::numeric, 2) AS avg_product_rating
FROM customer_behaviour
WHERE review_rating IS NOT NULL
GROUP BY item_purchased
HAVING COUNT(*) >= 10
ORDER BY avg_product_rating DESC, total_reviews DESC
LIMIT 5;


-- ============================================
-- Q4: Compare average spending between
-- Standard and Express shipping.
-- ============================================

SELECT
    shipping_type,
    COUNT(*) AS total_orders,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_purchase_amount,
    ROUND(SUM(purchase_amount)::numeric, 2) AS total_revenue
FROM customer_behaviour
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type
ORDER BY avg_purchase_amount DESC;


-- ============================================
-- Q5: Do subscribed customers spend more?
-- ============================================

SELECT
    subscription_status,
    COUNT(DISTINCT customer_id) AS total_customers,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_spend,
    ROUND(SUM(purchase_amount)::numeric, 2) AS total_revenue
FROM customer_behaviour
GROUP BY subscription_status
ORDER BY avg_spend DESC;


-- ============================================
-- Q6: Which 5 products have the highest
-- percentage of purchases with discounts?
-- ============================================

SELECT
    item_purchased,
    COUNT(*) AS total_purchases,
    SUM(
        CASE
            WHEN discount_applied = 'Yes' THEN 1
            ELSE 0
        END
    ) AS discounted_purchases,
    ROUND(
        SUM(
            CASE
                WHEN discount_applied = 'Yes' THEN 1.0
                ELSE 0.0
            END
        ) * 100.0 / NULLIF(COUNT(*), 0),
        2
    ) AS discount_rate_percentage
FROM customer_behaviour
GROUP BY item_purchased
ORDER BY discount_rate_percentage DESC, total_purchases DESC
LIMIT 5;


-- ============================================
-- Q7: Segment customers into New, Returning,
-- and Loyal based on previous purchases.
-- ============================================

WITH customer_type AS (
    SELECT
        customer_id,
        previous_purchases,
        CASE
            WHEN previous_purchases IS NULL THEN 'Unknown'
            WHEN previous_purchases <= 1 THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS customer_segment
    FROM customer_behaviour
)
SELECT
    customer_segment,
    COUNT(DISTINCT customer_id) AS total_customers,
    ROUND(
        COUNT(DISTINCT customer_id) * 100.0 /
        NULLIF(SUM(COUNT(DISTINCT customer_id)) OVER (), 0),
        2
    ) AS customer_percentage
FROM customer_type
GROUP BY customer_segment
ORDER BY total_customers DESC;


-- ============================================
-- Q8: What are the top 3 most purchased
-- products within each category?
-- ============================================

WITH item_counts AS (
    SELECT
        category,
        item_purchased,
        COUNT(*) AS total_orders,
        ROW_NUMBER() OVER (
            PARTITION BY category
            ORDER BY COUNT(*) DESC, item_purchased
        ) AS item_rank
    FROM customer_behaviour
    GROUP BY category, item_purchased
)
SELECT
    category,
    item_rank,
    item_purchased,
    total_orders
FROM item_counts
WHERE item_rank <= 3
ORDER BY category, item_rank;


-- ============================================
-- Q9: Are repeat buyers more likely to subscribe?
-- Repeat buyers = more than 5 previous purchases.
-- ============================================

SELECT
    subscription_status,
    COUNT(DISTINCT customer_id) AS total_repeat_buyers,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_purchase_amount,
    ROUND(SUM(purchase_amount)::numeric, 2) AS total_revenue
FROM customer_behaviour
WHERE previous_purchases > 5
GROUP BY subscription_status
ORDER BY total_repeat_buyers DESC;


-- ============================================
-- Q10: What is the revenue contribution
-- of each age group?
-- ============================================

SELECT
    age_group,
    COUNT(*) AS total_purchases,
    ROUND(SUM(purchase_amount)::numeric, 2) AS total_revenue,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_purchase_amount,
    ROUND(
        SUM(purchase_amount) * 100.0 /
        NULLIF(SUM(SUM(purchase_amount)) OVER (), 0),
        2
    ) AS revenue_percentage
FROM customer_behaviour
GROUP BY age_group
ORDER BY total_revenue DESC;


-- ============================================
-- Q11: Which product categories generate
-- the highest revenue?
-- ============================================

SELECT
    category,
    COUNT(*) AS total_purchases,
    ROUND(SUM(purchase_amount)::numeric, 2) AS total_revenue,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_purchase_amount
FROM customer_behaviour
GROUP BY category
ORDER BY total_revenue DESC;


-- ============================================
-- Q12: Which seasons generate the most revenue?
-- ============================================

SELECT
    season,
    COUNT(*) AS total_purchases,
    ROUND(SUM(purchase_amount)::numeric, 2) AS total_revenue,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_purchase_amount
FROM customer_behaviour
GROUP BY season
ORDER BY total_revenue DESC;


-- ============================================
-- Q13: Which payment methods are most popular?
-- ============================================

SELECT
    payment_method,
    COUNT(*) AS total_purchases,
    ROUND(
        COUNT(*) * 100.0 /
        NULLIF(SUM(COUNT(*)) OVER (), 0),
        2
    ) AS purchase_percentage,
    ROUND(SUM(purchase_amount)::numeric, 2) AS total_revenue
FROM customer_behaviour
GROUP BY payment_method
ORDER BY total_purchases DESC;


-- ============================================
-- Q14: Which categories have the highest
-- average customer ratings?
-- ============================================

SELECT
    category,
    COUNT(review_rating) AS total_reviews,
    ROUND(AVG(review_rating)::numeric, 2) AS avg_rating
FROM customer_behaviour
WHERE review_rating IS NOT NULL
GROUP BY category
ORDER BY avg_rating DESC;


-- ============================================
-- Q15: How does subscription status vary
-- across discount usage?
-- ============================================

SELECT
    subscription_status,
    discount_applied,
    COUNT(DISTINCT customer_id) AS total_customers,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_purchase_amount,
    ROUND(SUM(purchase_amount)::numeric, 2) AS total_revenue
FROM customer_behaviour
GROUP BY subscription_status, discount_applied
ORDER BY subscription_status, total_revenue DESC;


-- ============================================
-- Q16: What is the overall business performance?
-- ============================================

SELECT
    COUNT(*) AS total_records,
    COUNT(DISTINCT customer_id) AS unique_customers,
    ROUND(SUM(purchase_amount)::numeric, 2) AS total_revenue,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_purchase_amount,
    ROUND(AVG(review_rating)::numeric, 2) AS avg_review_rating
FROM customer_behaviour;
